import { createRouter, createWebHashHistory } from 'vue-router';
import jsCookie from 'js-cookie';
// main
// import Home from "@/views/MainPage";
// user
import registerPage from '@/views/user/RegisterPage';
import login from '@/views/user/LoginPage';
// func
import func1 from '@/views/func/FuncPage1';
// import test  from "@/views/TestPage";
// cat
import cat from '@/views/cat/CatPage';

// 定义路由
const router = createRouter({
    mode: 'hash',
    history: createWebHashHistory(process.env.BASE_URL),
    routes: [
        {
            path: '/',
            name: 'Home',
            // component: Home
            component: cat
        },
        {
            path: '/user',
            name: 'user',
            children: [
                {
                    path: 'register',
                    name: 'register',
                    component: registerPage
                },
                {
                    path: 'login',
                    name: 'login',
                    component: login
                },
            ]
        },
        {
            path: '/cat',
            name: 'cat',
            component: cat,
            meta: { guard: true }, // 标识该一级路由需要认证
            // children: [
            //     {
            //         path: '/',
            //         name: 'cat',
            //     },
            // ]
        },
        {
            path: '/func',
            name: 'func',
            meta: { guard: true }, // 标识该一级路由需要认证
            children: [
                {
                    path: 'func1',
                    name: 'func1',
                    component: func1,
                    // meta: { guard: true }, // 标识该二级路由需要认证
                },
            ]
        },   
    ]
});

// 路由守卫
router.beforeEach((to, from, next) => {
    // 获取 access_token
    const accessToken = jsCookie.get('access_token');
    
    // 检查是否需要认证
    if (to.meta.guard) {
        if (!accessToken) {
            // 如果没有 access_token，重定向到登录页面
            next({ name: 'login' });
        } else {
            // 如果有 access_token，继续导航
            next();
        }
    } else {
        // 如果不需要认证，继续导航
        next();
    }
});

export default router;