<template>
  <div class="register-container">
    <div class="register-box">
      <h2>邮箱注册</h2>
      <form @submit.prevent="register">
        <div class="form-group">
          <label for="username">用户名</label>
          <input type="text" id="username" v-model="username" required />
        </div>
        <div class="form-group">
          <label for="email">邮箱</label>
          <input type="email" id="email" v-model="email" required />
        </div>
        <div class="form-group">
          <label for="password">密码</label>
          <input type="password" id="password" v-model="password" required />
        </div>
        <div class="form-group">
          <label for="confirmPassword">确认密码</label>
          <input type="password" id="confirmPassword" v-model="confirmPassword" required />
        </div>
        <button type="submit" class="register-button">注册</button>
      </form>
      <div class="register-link">
        <a @click="goToLogin"><u>去登录</u></a>
      </div>
    </div>
  </div>
</template>

<script>
import { register } from '@/api/user/register_api.js'; // 导入注册方法
import jsCookie from 'js-cookie';

export default {
  data() {
    return {
      username: '',
      email: '',
      password: '',
      confirmPassword: ''
    };
  },
  methods: {
    register() {
      if (this.password !== this.confirmPassword) {
        alert("密码和确认密码不一致");
      } else {
        // 调用统一的注册方法
        register({
          username: this.username,
          password: this.password,
          email: this.email
        })
          .then(() => {
            alert("注册成功");
            jsCookie.remove('access_token');
            jsCookie.remove('refresh_token');
            this.goToLogin();
          })
          .catch(error => {
            let errorMessage = '注册失败';
            if (error.response) {
              // 从响应数据中获取错误信息
              errorMessage = error.response.data ? error.response.data.trim() : '服务器返回空数据';
            } else if (error.request) {
              // 请求已发送，但未收到响应
              errorMessage = '请求已发送，但未收到响应';
            } else {
              // 其他错误
              errorMessage = `注册失败: ${error.message}`;
            }
            alert(errorMessage);
            console.error('注册失败:', errorMessage);
          });
      }
    },
    goToLogin() {
      try {
        this.$router.push({ name: 'login' });
      } catch (error) {
        console.error('路由跳转错误:', error);
      }
    }
  }
};
</script>

<style scoped>
/* 样式部分保持不变 */
html {
  font-size: 16px;
}

.register-container {
  width: 100vw;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.register-box {
  width: 100%;
  max-width: 22rem;
  padding: 1.5rem;
  background-color: #fff;
  border-radius: 0.5rem;
  box-shadow: 0 0 1rem rgba(0, 0, 0, 0.1);
}

h2 {
  text-align: center;
  color: #333;
  margin-bottom: 1rem;
  font-size: 1.5rem;
}

.form-group {
  margin-bottom: 1rem;
}

label {
  display: block;
  margin-bottom: 0.5rem;
  color: #555;
  font-size: 1rem;
}

input[type="text"],
input[type="email"],
input[type="password"] {
  width: 100%;
  padding: 0.8rem;
  border: 1px solid #ddd;
  border-radius: 0.3rem;
  box-sizing: border-box;
  font-size: 1rem;
}

.register-button {
  width: 100%;
  padding: 1rem;
  background-color: #4caf50;
  color: white;
  border: none;
  border-radius: 0.3rem;
  cursor: pointer;
  font-size: 1.1rem;
}

.register-button:hover {
  background-color: #45a049;
}

.register-link {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  margin-top: 1rem;
  cursor: pointer;
}
</style>