<template>
    <div class="sidebar" :style="sidebarStyle">
        <div class="sidebar-content">
            <!-- 表情文字替代 Logo 和标题 -->
            <div class="emoji-section" @click="goToCat">
                <span class="emoji-text" @mouseover="changeEmoji(true)" @mouseout="changeEmoji(false)">
                    {{ currentEmoji }}
                </span>
            </div>

            <!-- 通用图标按钮 -->
            <div class="cat_button" @click="handleIconClick">
                <img :src="require('@/assets/planet.svg')" alt="SVG Icon" class="svg-icon" />
            </div>
            <div class="cat_button" @click="handleIconClick">
                <img :src="require('@/assets/pack.svg')" alt="SVG Icon" class="svg-icon" />
            </div>
            <div class="cat_button" @click="handleIconClick">
                <img :src="require('@/assets/setting.svg')" alt="SVG Icon" class="svg-icon" />
            </div>

            <!-- 退出登录按钮 -->
            <button class="logout-button" @mouseover="changeLogoutText(true)" @mouseout="changeLogoutText(false)"
                @click="handleLogout"
                >
                <span class="logout-text">{{ logoutText }}</span>
            </button>
        </div>
    </div>
</template>

<script>
// import { outLogin } from '@/api/user/user_api.js';

export default {
    props: {
        normalColor: {
            type: Boolean,
            default: true
        }
    },
    data() {
        return {
            currentEmoji: '(=ω=)',
            isHovered: false,
            logoutText: '退出登录'
        };
    },
    computed: {
        sidebarStyle() {
            if (this.normalColor) {
                return {
                    'background-color': 'rgba(255, 255, 255, 0.95)',
                    'backdrop-filter': 'blur(5px)'
                };
            } else {
                return {
                    'background-color': 'rgba(106, 90, 205, 0.95)', // 可以换成其他颜色
                    'backdrop-filter': 'blur(5px)'
                };
            }
        }
    },
    methods: {
        goToCat() {
            try {
                this.$router.push({ name: 'cat' });
            } catch (error) {
                console.error('路由跳转错误:', error);
            }
        },
        handleLogout() {
            // outLogin();
        },
        changeEmoji(isHover) {
            if (isHover) {
                this.currentEmoji = '(=`ω´=)';
            } else {
                this.currentEmoji = '(=ω=)';
            }
        },
        changeLogoutText(isHover) {
            if (isHover) {
                this.currentEmoji = 'Σ(°△°|||)';
            } else {
                this.currentEmoji = '(=ω=)';
            }
        },
        handleIconClick() {
            console.log('Icon clicked!');
        }
    }
};
</script>

<style scoped>
.sidebar {
    width: 7vw;
    height: 50vh;
    border-radius: 1.5rem;
    box-shadow: 0 0 16rem rgba(0, 0, 0, 0.1);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    position: relative;
}

/* 创建一个伪元素作为毛玻璃背景 */
.sidebar::before {
    border-radius: 2rem;
    content: "";
    position: absolute;
    width: 100%;
    height: 100%;
    z-index: 0;
}

.sidebar-content {
    z-index: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    width: 100%;
    height: 100%;
    padding: 3% 0;
    color: #333;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: center;
}

.emoji-section {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-top: 2.5vh;
    margin-bottom: 0.5vh;
}

.emoji-text {
    font-size: 1.2vw;
    font-weight: bold;
    transition: all 0.3s ease;
    user-select: none;
}

.emoji-text:hover {
    transform: scale(1.2);
    color: #ff6b6b;
    cursor: pointer;
}

/* 通用图标按钮容器 */
.cat_button {
    width: 3vw;
    height: 3vw;
    margin: 0.2vh 0;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    justify-content: center;
    align-items: center;
    background-color: transparent;
    border: none;
    padding: 0;
    border-radius: 50%;
    overflow: visible;
}

.cat_button:hover {
    transform: rotate(15deg);
}

.svg-icon {
    width: 80%;
    height: 80%;
    object-fit: contain;
    transition: all 0.3s ease;
}

.logout-button {
    background-color: rgba(231, 76, 60, 0.8);
    color: white;
    border: none;
    padding: 0.7vw 0;
    border-radius: 1rem;
    cursor: pointer;
    font-size: 0.8vw;
    width: 70%;
    transition: all 0.3s ease;
    margin-top: 0.5vh;
    margin-bottom: 1.5vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.logout-button:hover {
    background-color: rgba(192, 57, 43, 0.9);
    transform: scale(1.05);
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
}

.logout-text {
    transition: all 0.3s ease;
}
</style>